using SoulsFormats;using System.Security.Cryptography;using System.Text.Json;
string source=args[0],native=args[1],defs=args[2];var files=new Dictionary<string,byte[]>(StringComparer.Ordinal);var hashes=new Dictionary<string,string>();
byte[] Read(string root,string path){string file=Path.Combine(root,path);var b=File.ReadAllBytes(file);hashes.TryAdd(file,Convert.ToHexStringLower(SHA256.HashData(b)));return b;}byte[]? Src(string p)=>File.Exists(Path.Combine(source,p))?Read(source,p):null;
byte[]? Native(string p)=>files.GetValueOrDefault(p)??(File.Exists(Path.Combine(native,p))?Read(native,p):null);
string Leaf(string p)=>p.Replace('\\','/').Split('/').Last();void Check(bool b,string why){if(!b)throw new Exception(why);}int Constant(byte[] b)=>b.Length==2?b[0]-64:BitConverter.ToInt32(b,1);
void Reject(Action a,string why){try{a();}catch(Exception e)when(e is InvalidDataException or NotSupportedException or ArgumentException){return;}throw new Exception("Accepted "+why);}
PARAM Param(BND4 game,string type){var p=PARAM.Read(game.Files.Single(f=>Leaf(f.Name)==type+".param").Bytes);p.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.Combine(defs,"../../BB/Defs/"+type+".xml")));return p;}
string Cells(PARAM.Row r)=>JsonSerializer.Serialize(r.Cells.Select(c=>c.Value));
var original=BND4.Read(Native("param/gameparam/gameparam.parambnd.dcx")!);var reports=new List<MapMerchantTalk.Result>();
foreach(var (sourceMap,target,entity,sourceEntity,model) in new[]{("m10_02_00_00","m40_02_00_00",2419703,6240,"c8903"),("m10_01_00_00","m40_03_00_00",4039700,6230,"c8904")}){
 string talkPath="script/talk/"+target+".talkesdbnd.dcx";files[talkPath]=Native("script/talk/m21_00_00_00.talkesdbnd.dcx")!;var scene=new MSBB();var actor=new MSBB.Part.Enemy{Name=model+"_merchant",ModelName=model,EntityID=entity,TalkID=-1};scene.Parts.Enemies.Add(actor);
 var binding=new Dictionary<int,int>{{sourceEntity,entity}};
 if(sourceEntity==6240){string occupied="event/new-owned.emevd.dcx";files[occupied]=BitConverter.GetBytes(52100960);var beforeConflict=files.ToDictionary(p=>p.Key,p=>SHA256.HashData(p.Value));Reject(()=>MapMerchantTalk.Export(scene,sourceMap,target,native,defs,Src,Native,binding,(p,b)=>files[p]=b,files),"composed-only stock flag conflict");Check(actor.TalkID==-1&&beforeConflict.All(p=>SHA256.HashData(files[p.Key]).SequenceEqual(p.Value)),"stock flag failure mutated outputs");files.Remove(occupied);}
 if(sourceEntity==6230){var g=BND4.Read(Native("param/gameparam/gameparam.parambnd.dcx")!);var entry=g.Files.Single(f=>Leaf(f.Name)=="EquipParamGoods.param");var goods=Param(g,"EquipParamGoods");var existing=new PARAM.Row(goods.Rows.Single(r=>r.ID==4000)){ID=902021,Name="Imported DS1R good 2021"};existing["maxNum"].Value=(short)1;existing["isConsume"].Value=(byte)0;goods.Rows.Add(existing);entry.Bytes=goods.Write();files["param/gameparam/gameparam.parambnd.dcx"]=g.Write(g.Compression);}
 var result=MapMerchantTalk.Export(scene,sourceMap,target,native,defs,Src,Native,binding,(p,b)=>files[p]=b,files);reports.Add(result);Check(result.Actors.Count==1&&result.ShopRows.Count>0&&actor.TalkID==int.Parse(target[1..3])*10000+int.Parse(target[4..6])*1000+975,"merchant actor/talk binding");
 var game=BND4.Read(files["param/gameparam/gameparam.parambnd.dcx"]);var shop=Param(game,"ShopLineupParam");Check(result.ShopRows.All(s=>s.SourceGood<100000&&Convert.ToInt32(shop.Rows.Single(r=>r.ID==s.NativeRow)["equipType"].Value)==3),"equipment or category confusion");
 var esd=ESD.Read(BND4.Read(files[talkPath]).Files.Single(f=>Leaf(f.Name)==$"t{actor.TalkID}.esd").Bytes);Check(esd.Name==$"t{actor.TalkID}"&&esd.LongFormat&&esd.DarkSoulsCount==2&&esd.StateGroups.Count==1,"native ESD serialization");var states=esd.StateGroups[1];Check(states.Count==6&&states[1].Conditions.Single().TargetState==2&&states[2].EntryCommands.Single().CommandID==1&&states[3].EntryCommands.Single().CommandID==22,"greeting/shop graph");Check(states[3].EntryCommands.Single().Arguments.Select(Constant).SequenceEqual(new[]{result.ShopRows.First().NativeRow,result.ShopRows.Last().NativeRow}),"shop range");Check(states[3].Conditions.Last().Evaluator.SequenceEqual(new byte[]{0x7b,0x4b,0x40,0x86,0xa6,0x40,0x95,0xa1}),"native menu close expression");Check(states[2].Conditions.Select(c=>c.TargetState).SequenceEqual(new long?[]{4,3})&&states[4].EntryCommands.Select(c=>c.CommandID).SequenceEqual(new[]{71,8,9,36}),"interrupt/completion cleanup");
 foreach(var row in result.ShopRows){var r=shop.Rows.Single(r=>r.ID==row.NativeRow);Check(Convert.ToInt32(r["equipId"].Value)==row.NativeGood&&Convert.ToInt32(r["value"].Value)==row.Price&&Convert.ToInt32(r["sellQuantity"].Value)==row.Quantity&&Convert.ToInt32(r["eventFlag"].Value)==row.StockFlag,"source stock/cost conversion");}
 var before=files.ToDictionary(p=>p.Key,p=>SHA256.HashData(p.Value));int talkBefore=actor.TalkID;Reject(()=>MapMerchantTalk.Export(scene,sourceMap,target,native,defs,Src,Native,binding,(p,b)=>files[p]=b),"duplicate actor/export");Check(actor.TalkID==talkBefore&&before.All(p=>SHA256.HashData(files[p.Key]).SequenceEqual(p.Value)),"failed export mutated staged files/actor");
 Console.WriteLine($"PASS {sourceMap}: {result.ShopRows.Count} goods, {result.Actors.Single().Lines} authentic lines, native purchase graph");
}
var final=BND4.Read(files["param/gameparam/gameparam.parambnd.dcx"]);foreach(string type in new[]{"ShopLineupParam","TalkParam","EquipParamGoods"}){var a=Param(original,type);var b=Param(final,type);foreach(var group in a.Rows.GroupBy(r=>r.ID)){var rows=b.Rows.Where(r=>r.ID==group.Key).ToArray();Check(rows.Length==group.Count(),"original duplicate row count changed");foreach(var pair in group.Zip(rows))Check(pair.First.Name==pair.Second.Name&&Cells(pair.First)==Cells(pair.Second),"original native row changed: "+type+"/"+group.Key);}}
foreach(var f in original.Files.Where(f=>!new[]{"ShopLineupParam.param","TalkParam.param","EquipParamGoods.param"}.Contains(Leaf(f.Name))))Check(final.Files.Single(x=>x.ID==f.ID).Bytes.Span.SequenceEqual(f.Bytes.Span),"unrelated native parameter entry changed");
foreach(var(path,hash) in hashes)Check(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)))==hash,"source/native input modified");
Check(reports[0].ShopRows.Any(s=>s.SourceGood==500&&s.Quantity==1)&&reports[1].ShopRows.Any(s=>s.SourceGood==2021&&s.NativeGood==902021&&s.Quantity==1),"finite humanity/residence key missing");Check(reports.SelectMany(r=>r.ShopRows).Where(s=>s.StockFlag>0).Select(s=>s.StockFlag).Distinct().Count()==4,"stock flags overlap");
Directory.CreateDirectory("out/map-editor/merchant-talk-tests");File.WriteAllText("out/map-editor/merchant-talk-tests/report.json",JsonSerializer.Serialize(new{Status="PASS",Reports=reports,InputsPreserved=hashes.Count,Limits="Installed-asset format/stategraph fixture; native purchase/save/stock behavior still requires gameplay."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS original native rows/assets preserved, connected composition, reservations and atomic failure");
